import time, mujoco, numpy as np
base = open("model_ref.xml").read()
def build(opt):
    return base.replace('<compiler autolimits="true"/>', f'<compiler autolimits="true"/>\n  <option {opt}/>')
def mk(xml):
    m=mujoco.MjModel.from_xml_string(xml); return m, mujoco.MjData(m)
xmls={
 "ref": build(''),
 "pgs_sparse": build('solver="PGS" tolerance="1e-12" iterations="200"'),
 "pgs_dense": build('solver="PGS" tolerance="1e-12" iterations="200" jacobian="dense"'),
 "cg": build('solver="CG" tolerance="1e-12" iterations="200"'),
}
models={k:mk(v) for k,v in xmls.items()}
def bench(m,d,reps=5):
    best=1e9
    for _ in range(reps):
        t=time.perf_counter()
        for _ in range(1000): mujoco.mj_step(m,d)
        best=min(best,time.perf_counter()-t)
    return best
for k,(m,d) in models.items():
    for _ in range(200): mujoco.mj_step(m,d)   # settle
    b=bench(m,d)
    print(f"{k:12s} {b*1000:7.1f} ms/1000steps -> rel {b/bench(*models['ref']):.3f}")
EOF
